import json

def solve(x):
    data = json.loads(x)
    label_changes = {}

    for item in data:
        label = item['label']
        value = item['value']

        if label not in label_changes:
            label_changes[label] = {'prev': 0, 'total': 0}

        prev = label_changes[label]['prev']
        change = (value - prev) % 13
        label_changes[label]['total'] += change
        label_changes[label]['prev'] = value

    return {label: changes['total'] for label, changes in label_changes.items()}

