def solve(x):
    import re
    sections = re.split(r'\n\s*$$', x.strip())
    label_values = {}
    for section in sections:
        if not section:
            continue
        key, value = re.search(r'label\s*=\s*([a-z]+)', section).group(1), int(re.search(r'value\s*=\s*(\d+)', section).group(1))
        if key in label_values:
            label_values[key].append(value)
        else:
            label_values[key] = [value]
    result = []
    for label in label_values:
        if label not in result and any(v >= 8 for v in label_values[label]):
            result.append(label)
    return result
