def solve(x):
    import re
    sections = re.split(r'\n\s*\n', x.strip())
    label_sums = {}
    for section in sections:
        if not section:
            continue
        key, value = re.search(r'label\s*=\s*([a-z]+)', section).group(1), int(re.search(r'value\s*=\s*(\d+)', section).group(1))
        if key not in label_sums:
            label_sums[key] = 0
        if value >= 3:
            label_sums[key] += value
    # Sort by sum (descending), then by first appearance (ascending)
    sorted_labels = sorted(label_sums.keys(), key=lambda k: (-label_sums[k], k))
    return sorted_labels
